# ---------- helpers ----------
def classify(p):
    p = p.strip()
    if not p: return None
    n = len(p)
    endpunct = ['。','？','！','?','!','.','；',';','——']
    if n <= 20 and (not any(p.endswith(c) for c in endpunct) or p.endswith('：') or p.endswith(':')):
        return {'t':'h','x':p}
    if n <= 30 and (p.endswith('：') or p.endswith(':') or not any(p.endswith(c) for c in endpunct)):
        if '，' not in p and ',' not in p:
            return {'t':'h','x':p}
    return {'t':'p','x':p}

def to_blocks(v):
    """Normalize string / list-of-strings / list-of-dicts into [{'t','x'}]."""
    out = []
    if not v: return out
    if isinstance(v, str):
        parts = [x.strip() for x in v.split('\n\n') if x.strip()]
        for p in parts:
            b = classify(p)
            if b: out.append(b)
        return out
    for item in v:
        if isinstance(item, dict):
            t = 'h' if item.get('type') == 'heading' else 'p'
            x = (item.get('text') or '').strip()
            if x: out.append({'t':t,'x':x})
        elif isinstance(item, str):
            b = classify(item)
            if b: out.append(b)
    return out

