    "file_text": "// Render preview to verify polygons project correctly within China's bounds
const fs = require('fs');
const d3 = require('d3');

// Load data
const dataCode = fs.readFileSync('data.js', 'utf-8');
const DATA = (new Function('var window = {}; ' + dataCode + '; return window.DATA;'))();

const W = 1000, H = 760;
const projection = d3.geoMercator().center([105, 36]).scale(720).translate([W/2, H/2]);
const pathGen = d3.geoPath().projection(projection);

function polyToFeat(coords) {
  return { type: "Feature", geometry: { type: "Polygon", coordinates: [coords] } };
}

let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" style="background:#f3e9cf">`;

// Reference China bounding box for sanity
svg += `<rect x="0" y="0" width="${W}" height="${H}" fill="#f3e9cf"/>`;

// Render terrain (under)
DATA.terrain.forEach(t => {
  const p = pathGen(polyToFeat(t.polygon));
  svg += `<path d="${p}" fill="${t.color}" fill-opacity="0.3" stroke="${t.color}" stroke-width="0.5"/>`;
});

// Render dialects
DATA.dialects.forEach(d => {
  const polys = d.polygons || [d.polygon];
  polys.forEach(poly => {
    const p = pathGen(polyToFeat(poly));
    svg += `<path d="${p}" fill="${d.color}" fill-opacity="0.4" stroke="${d.color}" stroke-width="0.6"/>`;
  });
});

// Render non-Han
DATA.nonHan.forEach(n => {
  const p = pathGen(polyToFeat(n.polygon));
  svg += `<path d="${p}" fill="${n.color}" fill-opacity="0.35" stroke="${n.color}" stroke-width="0.8" stroke-dasharray="3 2"/>`;
});

// Render enclaves
DATA.enclaves.forEach(e => {
  const p = pathGen(polyToFeat(e.polygon));
  svg += `<path d="${p}" fill="${e.color}" fill-opacity="0.55" stroke="${e.color}" stroke-width="1.2"/>`;
});

// Annotations
DATA.annotations.forEach(a => {
  const [x, y] = projection([a.lng, a.lat]);
  svg += `<circle cx="${x}" cy="${y}" r="3" fill="#b03a2e"/>`;
  svg += `<text x="${x+5}" y="${y+3}" font-size="9" font-family="serif" fill="#1f1a14">${a.name}</text>`;
});

svg += `</svg>`;

fs.writeFileSync('preview.svg', svg);
console.log('Rendered', DATA.dialects.length, 'dialects,', DATA.terrain.length, 'terrains,', DATA.nonHan.length, 'non-Han,', DATA.enclaves.length, 'enclaves,', DATA.annotations.length, 'annotations');
console.log('SVG size:', svg.length, 'chars');
