      if (f === 0.9 || f === 1 || f === 1.12) this.globalData.fontScale = f;
    } catch (e) {}
  },

  setTheme(theme) {
    this.globalData.theme = theme;
    try { wx.setStorageSync('theme', theme); } catch (e) {}
  },

  setFontScale(scale) {
    this.globalData.fontScale = scale;
    try { wx.setStorageSync('fontScale', scale); } catch (e) {}
  }
});
