    "new_str": "  // 考点标记(黄点) — 带防重叠错位
  const kpPositions = state.route.kp.map(k => posAtWaypoint(k.at));
  // 计算每个标号的偏移(避免重叠): 若与前一个屏幕距离过近,上下错开
  const labelOffsets = computeLabelOffsets(kpPositions);
  state.route.kp.forEach((k, idx) => {
    const pos = kpPositions[idx];
    const isCur = (idx === state.curStep);
    const r = isCur ? 7 : 4.5;
    ctx.fillStyle = isCur ? '#f5a623' : '#e6b800';
    ctx.beginPath();
    ctx.arc(WX(pos.x), WY(pos.y), r, 0, Math.PI*2);
    ctx.fill();
    if (isCur) {
      ctx.strokeStyle = 'rgba(245,166,35,0.4)';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(WX(pos.x), WY(pos.y), r+4, 0, Math.PI*2);
      ctx.stroke();
    }
    // 序号(带错位)
    const off = labelOffsets[idx];
    const lx = WX(pos.x) + off.dx;
    const ly = WY(pos.y) + off.dy;
    if (off.dx !== 0 || off.dy !== 0) {
      // 错位时画一条细引线
      ctx.strokeStyle = 'rgba(230,184,0,0.5)';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(WX(pos.x), WY(pos.y));
      ctx.lineTo(lx, ly);
      ctx.stroke();
      // 错位标号画小圆底
      ctx.fillStyle = isCur ? '#f5a623' : '#e6b800';
      ctx.beginPath();
      ctx.arc(lx, ly, isCur?8:6.5, 0, Math.PI*2);
      ctx.fill();
    }
    ctx.fillStyle = '#0f1419';
    ctx.font = `bold ${isCur?10:8.5}px sans-serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText((idx+1), lx, ly);
  });",
