{
  "message": "添加标号防重叠计算函数",
  "input": {
    "description": "添加标号防重叠计算函数",
    "new_str": "// 计算考点标号偏移,避免相邻标号在屏幕上重叠
function computeLabelOffsets(positions){
  const offsets = positions.map(()=>({dx:0, dy:0}));
  const MIN_DIST = 20; // 屏幕像素最小间距
  const screenPos = positions.map(p => ({x: WX(p.x), y: WY(p.y)}));
  for (let i=1; i<screenPos.length; i++){
    for (let j=0; j<i; j++){
      const ax = screenPos[i].x + offsets[i].dx;
      const ay = screenPos[i].y + offsets[i].dy;
      const bx = screenPos[j].x + offsets[j].dx;
      const by = screenPos[j].y + offsets[j].dy;
      const d = Math.hypot(ax-bx, ay-by);
      if (d < MIN_DIST){
        // 判断路段方向:相邻航点决定标号往哪个垂直方向错开
        // 简单策略:若两点水平接近→上下错;若垂直接近→左右错
        const dxRaw = Math.abs(screenPos[i].x - screenPos[j].x);
        const dyRaw = Math.abs(screenPos[i].y - screenPos[j].y);
        if (dxRaw <= dyRaw){
          // 垂直道路:标号左右错开
          offsets[i].dx = (offsets[j].dx >= 0) ? -16 : 16;
        } else {
          // 水平道路:标号上下错开
          offsets[i].dy = (offsets[j].dy <= 0) ? 17 : -17;
        }
      }
    }
  }
  return offsets;
}

