  "message": "Verify CUMPRINC and CUMIPMT match Excel",
  "input": {
    "command": "cd /home/claude && cat > verify_cumipmt.py << 'EOF'
import math

def pmt(rate, nper, pv, fv=0, type=0):
    if rate == 0: return -(pv + fv) / nper
    pvif = (1 + rate) ** nper
    p = -rate * (pv * pvif + fv) / (pvif - 1)
    if type == 1: p /= (1 + rate)
    return p

def fv_fn(rate, nper, pmt_val, pv, type=0):
    if rate == 0: return -(pv + pmt_val * nper)
    pvif = (1 + rate) ** nper
    return -(pv * pvif + pmt_val * (1 + rate * type) * (pvif - 1) / rate)

def ipmt(rate, per, nper, pv, fv_val=0, type=0):
    p = pmt(rate, nper, pv, fv_val, type)
    if per == 1:
        if type == 1: return 0
        return -pv * rate
    bal = fv_fn(rate, per - 1, p, pv, type)
    if type == 1: return -bal * rate / (1 + rate)
    return -bal * rate

def ppmt(rate, per, nper, pv, fv_val=0, type=0):
    return pmt(rate, nper, pv, fv_val, type) - ipmt(rate, per, nper, pv, fv_val, type)

def cumipmt(rate, nper, pv, start, end, type=0):
    return sum(ipmt(rate, i, nper, pv, 0, type) for i in range(int(start), int(end)+1))

def cumprinc(rate, nper, pv, start, end, type=0):
