function chartSVG(items, years){
  const W=620,H=240,pl=38,pr=14,pt=14,pb=30;
  const iw=W-pl-pr, ih=H-pt-pb;
  let vals=[]; items.forEach(({ref})=>years.forEach(y=>{ if(ref.scores[y]!=null) vals.push(ref.scores[y]); }));
  if(vals.length===0) return '';
  let dmin=Math.min(...vals), dmax=Math.max(...vals);
  let yMin=Math.floor((dmin-2)/5)*5, yMax=Math.ceil((dmax+2)/5)*5;
  if(yMax===yMin) yMax=yMin+5;
  const xN=years.length;
  const xPos=i=> xN===1 ? pl+iw/2 : pl + iw*i/(xN-1);
  const yPos=v=> pt + ih*(1-(v-yMin)/(yMax-yMin));
  let svg='<svg viewBox="0 0 '+W+' '+H+'" width="100%" style="display:block">';
  // y gridlines
  const steps=4;
  for(let k=0;k<=steps;k++){
    const val=yMin+(yMax-yMin)*k/steps; const y=yPos(val);
    svg+='<line x1="'+pl+'" y1="'+y+'" x2="'+(W-pr)+'" y2="'+y+'" stroke="#e6dcc6" stroke-width="1"/>';
    svg+='<text x="'+(pl-6)+'" y="'+(y+3)+'" font-size="10" fill="#a09070" text-anchor="end">'+val.toFixed(0)+'</text>';
  }
  // x labels
  years.forEach((y,i)=>{ svg+='<text x="'+xPos(i)+'" y="'+(H-10)+'" font-size="10" fill="#8a7a5a" text-anchor="middle">'+y+'</text>'; });
  // lines
  items.forEach((it,idx)=>{
    const col=PALETTE[idx%PALETTE.length];
    const pts=[];
    years.forEach((y,i)=>{ const v=it.ref.scores[y]; if(v!=null) pts.push([xPos(i),yPos(v)]); });
    if(pts.length>1){
      let d='M'+pts[0][0]+' '+pts[0][1];
      for(let j=1;j<pts.length;j++) d+=' L'+pts[j][0]+' '+pts[j][1];
      svg+='<path d="'+d+'" fill="none" stroke="'+col+'" stroke-width="2.5" stroke-linejoin="round"/>';
    }
    pts.forEach(p=> svg+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3.5" fill="'+col+'"/>');
  });
  svg+='</svg>';
  return svg;
}

