    "description": "Detail page logic - data-driven chapter renderer with interactions",
    "file_text": "const { getChapter, getNav } = require('../../data/content.js');

Page({
  data: {
    chapter: null,
    activeThinker: 0,
    activeTab: 'types',
    prev: null,
    next: null
  },

  onLoad(query) {
    this._render(query && query.id ? query.id : 'prologue');
  },

  _render(id) {
    const chapter = getChapter(id);
    const nav = getNav(chapter.id);
    wx.setNavigationBarTitle({ title: chapter.roman + ' · ' + chapter.navTitle });
    this.setData({
      chapter: chapter,
      prev: nav.prev,
      next: nav.next,
      activeThinker: 0,
      activeTab: 'types'
    });
    // 回到顶部
    wx.pageScrollTo({ scrollTop: 0, duration: 0 });
  },

  // 第一章：切换思想家
  onThinkerTap(e) {
    const i = e.currentTarget.dataset.index;
    if (i === this.data.activeThinker) return;
    this.setData({ activeThinker: i });
  },

  // 第二章：切换标签
  onTabTap(e) {
